const head=(title,description,url,p='')=>`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="google-site-verification" content="ZcLes6Gcp4HDDqHMF7uUlssy00WjDbP_rXlndEgeJZw"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="https://vanderhell.github.io/${url}"><meta property="og:type" content="website"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="https://vanderhell.github.io/${url}"><meta property="og:image" content="https://vanderhell.github.io/lox-logo.png"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="${p}favicon.svg"><link rel="stylesheet" href="${p}assets/site.css"><script defer src="${p}analytics-config.js"></script><script defer src="${p}assets/analytics.js"></script><script defer src="${p}assets/site.js"></script></head>`;
