const card=(p,prefix='')=>{prefix=typeof prefix==='string'?prefix:'';const meta=[status(p),p.version,p.language,p.license].filter(Boolean).map(esc).join(' · ');return `<article class="portfolio-card" data-project-card data-group="${esc(p.group)}"><h3>${esc(p.name)}</h3><p>${esc(p.solution)}</p><small>${meta}</small><a href="${prefix}projects/${p.slug}.html">Open project</a></article>`};
