const detail=p=>{const scenarios=new Set(['loxdb','loxbudget','microsh','loxboot','iotspool','panicdump']);const hasScenario=scenarios.has(p.slug);const versionBadge=p.version?`<span class="badge">${esc(p.version)}</span>`:'';return `${head(`${p.name} — Vanderhell portfolio`,`${p.name}: ${p.problem}` ,`projects/${p.slug}.html`,'../')}<body data-project="${p.slug}">${nav('../')}<main id="main"><header class="hero product-hero"><div class="wrap"><div class="kicker">${esc(p.group)}</div><h1>${esc(p.name)}</h1><p class="slogan">${esc(p.problem)}</p><p>${esc(p.solution)}</p><div class="badges"><span class="badge status-${status(p).toLowerCase()}">${status(p)}</span>${versionBadge}<span class="badge">${esc(p.license)}</span><span class="badge">${esc(p.language)}</span></div><div class="actions"><a class="button primary" href="${p.repo}">GitHub</a><a class="button secondary" href="#quick-start">Quick Start</a></div><dl class="meta"><div><dt>Last verified</dt><dd>${p.lastVerified}</dd></div><div><dt>Platform scope</dt><dd>${esc(p.platform)}</dd></div></dl></div></header><section class="section"><div class="wrap content-grid"><article class="content"><h2>What it solves</h2><p>${esc(p.problem)}</p><h2>How it works</h2>${flow(p)}<h2>Use it when</h2><div class="use-grid">${p.use.map(x=>`<div class="panel">${esc(x)}</div>`).join('')}</div><h2 id="quick-start">Quick Start</h2><div class="code-wrap"><pre><code>${esc(p.code)}</code></pre></div>${hasScenario?`<h2>Real scenarios</h2><div class="scenario-stack">${p.use.slice(0,3).map((x,i)=>`<section class="scenario"><span class="scenario-no">0${i+1}</span><h3>${esc(x)}</h3><p>${esc(p.solution)}</p></section>`).join('')}</div>`:''}<h2>Engineering evidence</h2><ul>${p.evidence.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h2>Known limits</h2><ul>${p.limits.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></article><aside class="side panel"><strong>Project data</strong><a href="${p.repo}">Repository ↗</a><p><small>Verified ${p.lastVerified}</small></p></aside></div></section></main>${footer('../')}</body></html>`};
const groups=[['LOX Family',projects.filter(p=>p.group==='LOX')],['Micro Toolkit',projects.filter(p=>p.group==='Micro-toolkit')],['Axiom One primitives',primitives],['Beyond LOX',[...projects.filter(p=>p.group==='Beyond LOX'),...newProjects]]];
const specialExplainers={
 'basalt-net':`<h2>Durability and execution</h2><p>Jobs are durably accepted before handlers run. Recovery, leases and fencing coordinate work across restarts and SQL Server clients. Execution is at least once, so handlers with external side effects need idempotency or suitable fencing.</p><h2>Scheduling and workflows</h2><p>Supports delayed, interval, daily and cron scheduling, with timezone, overlap and misfire policies. Workflows are statically declared durable DAGs with explicit dependencies and dependency-failure policies.</p><h2>Storage and management</h2><p>Embedded storage fits a local application or machine. SQL Server lets multiple processes share a queue; each process executing work registers handlers and starts Basalt. BasaltDashboard is a separate WPF console; the management/monitoring API exposes health, queues, executions, failures, schedules, workflows, workers and cumulative statistics through the managed API.</p>`,
 'nexum':`<h2>Primitive and graph model</h2><p>A primitive evaluates <code>P_config(state, event) → (next_state, bounded_outputs)</code>. Configuration selects inputs, an ALU operation, predicate, optional state/event-field updates and bounded output masks. Program IR separates logical cells, state domains, edges, inputs and outputs from runtime array addresses.</p><h2>Build and execute</h2><p>The builder assigns deterministic identifiers and routing order; compiler helpers express foundational compositions. Lowering creates a graph over caller-provided arrays and graph execution uses FIFO order. Time and randomness are explicit events. Primitive and graph execution do not allocate; program, queues, domains, graph arrays and outputs use caller-owned or fixed bounded storage.</p><h2>Determinism and validation</h2><p>D1 is primitive determinism and D2 is ordered replay determinism. D3 schedule-independent determinism is a conservative graph-analysis result, not guaranteed for every graph. CTest coverage, fuzzing and sanitizer workflows are documented. Nexum is experimental research software, not production-ready or formally verified.</p>`,
 'implicitnet':`<h2>Implicit network operations</h2><p>For supported power-of-two node counts, nodes and links are derived from network size and a 64-bit state. The API provides inverse <code>in_map</code>/<code>in_unmap</code>, dimension-based implicit neighbors, deterministic <code>in_next</code> routing, and reversible <code>in_step</code>/<code>in_prev</code> event transitions. The graph is never materialized.</p><h2>Memory and verification</h2><p>The C17 library has no heap allocation, recursion, dependencies or mutable global state. C invariant tests and Python reference-oracle tests cross-check randomized mapping and routing behavior. ImplicitNet remains experimental and makes no cryptographic security or universally optimal routing claim.</p>`,
 'compost':`<h2>World model</h2><p>Compost treats binary input as FOOD in the simulator's terminology. Organisms are autonomous mathematical entities with internal state, energy/metabolism, structural bodies and territory, plus deterministic reproduction and death transitions. These describe simulator bookkeeping, not biological processes.</p><h2>Sandbox runtime and experiments</h2><p>Inbox files are copied into experiment-owned storage, partitioned into FOOD, and processed under local rules for resources, growth, maintenance, territory and competition. The runtime persists world state and writes observational telemetry; the observer reports state rather than directing organisms. Captured experiments and supplied inputs support reproducible comparisons; live telemetry may be eventually consistent.</p><p class="notice">Experimental artificial-life and complex-systems research project. Not a biological model or production data-processing system.</p>`
};
const specialDetail=p=>{const version=p.version?`<span class="badge">${esc(p.version)}</span>`:'';return `${head(`${p.name} — Vanderhell portfolio`,`${p.name}: ${p.problem}`,`projects/${p.slug}.html`,'../')}<body data-project="${p.slug}">${nav('../')}<main id="main"><header class="hero product-hero"><div class="wrap"><div class="kicker">${esc(p.group)}</div><h1>${esc(p.name)}</h1><p class="slogan">${esc(p.problem)}</p><p>${esc(p.solution)}</p><div class="badges"><span class="badge status-${status(p).toLowerCase()}">${status(p)}</span>${version}<span class="badge">${esc(p.license)}</span><span class="badge">${esc(p.language)}</span></div><div class="actions"><a class="button primary" href="${p.repo}">GitHub repository</a><a class="button secondary" href="#quick-start">Example</a></div><dl class="meta"><div><dt>Last verified</dt><dd>${p.lastVerified}</dd></div><div><dt>Platform / runtime</dt><dd>${esc(p.platform)}</dd></div></dl></div></header><section class="section"><div class="wrap content-grid"><article class="content"><h2>Purpose</h2><p>${esc(p.problem)}</p><h2>Execution model</h2>${flow(p)}${specialExplainers[p.slug]}<h2>Typical use</h2><div class="use-grid">${p.use.map(x=>`<div class="panel">${esc(x)}</div>`).join('')}</div><h2 id="quick-start">Quick start</h2><div class="code-wrap"><pre><code>${esc(p.code)}</code></pre></div><h2>Repository evidence</h2><ul>${p.evidence.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h2>Limits and status</h2><ul>${p.limits.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p><a href="../all-projects.html">All projects</a> · <a href="../beyond-lox.html">Additional projects</a></p></article><aside class="side panel"><strong>Project data</strong><a href="${p.repo}">GitHub repository</a><p>${esc(p.status)} · ${esc(p.language)} · ${esc(p.license)}</p><p><small>Verified ${p.lastVerified}</small></p></aside></div></section></main>${footer('../')}</body></html>`};
const axiomModules=[
 ['ONEARB','Round-robin arbiter','Scheduling','Stateful','eligible bit mask → arbiter cursor → selected winner','one_arb_init, one_arb_next','Caller initializes and retains arbiter state; winner exists only when an eligible request is selected.','Select fairly among currently eligible bounded work items.'],
 ['ONEBACKOFF','Saturating exponential delay','Retry timing','Stateless','base delay + attempt + maximum → capped delay','one_backoff_delay','Returns a bounded arithmetic delay; it does not schedule or wait.','Calculate a retry delay before passing it to an application timer.'],
 ['ONEBUF','Single producer/consumer state buffer','Buffer coordination','Stateful','operation + capacity/value → buffer state → status and indices/generation','one_buf','Coordinates state only; payload storage and concurrency discipline belong to the caller.','Coordinate a single producer/consumer handoff over caller-owned data.'],
 ['ONEDBUF','Two-slot producer/consumer buffer','Buffer coordination','Stateful','operation + two-slot state → publish/release result','one_dbuf','Only coordination state is provided; the caller owns payload storage and synchronization context.','Publish a new value while retaining a ready slot or selecting documented drop-old policy.'],
 ['ONEDEAD','Dead-zone transform','Signal conditioning','Stateless','signed/unsigned sample + bounds → output','one_dead_u32, one_dead_i32','Configured interval and numeric type define the accepted domain.','Suppress small sensor deviations by mapping the configured interval to zero.'],
 ['ONEEMA','Integer exponential moving average','Signal filtering','Stateful','sample + EMA state → updated filtered value','one_ema_init, one_ema_update','Caller owns initialized filter state; smoothing shift controls the documented integer update.','Smooth a noisy sampled sensor signal.'],
 ['ONEFIELD','Packed fixed-width values','Compact storage','Stateful descriptor','range + width + caller bytes; ID/value → packed bytes or decoded value','one_field_init_range, one_field_set_u32, one_field_get_u32','Backing storage is caller supplied and must meet the required size and range/width contract.','Store small configuration fields in a bounded byte array.'],
 ['ONEHYST','Two-threshold hysteresis','Signal conditioning','Stateful','sample + low/high thresholds + binary state → updated state','one_hyst_i32, one_hyst_u32','Requires low < high and state 0 or 1; state holds between thresholds.','Prevent a threshold-controlled output from chattering near one boundary.'],
 ['ONEIDX','Numeric or symbolic key to index','Lookup mapping','Stateful descriptor','configured range/keys + ID/key → bounded slot index','one_idx_init_range, one_idx_index_u32','Provides lookup mapping, not payload storage; caller defines the valid range or symbols.','Map stable IDs to offsets in an application-owned array.'],
 ['ONEINIT','Ordered initialization runner','Startup sequencing','Stateless','ordered function array → invoke each function in order','one_init_run','Runs supplied functions in order; initialization functions and their effects are caller-defined.','Express driver initialization before application initialization.'],
 ['ONEOUTLIER','Accepted-sample delta guard','Input validation','Stateful','sample + accepted reference + max delta → accept/reject and reference update','one_outlier_init, one_outlier_accept','The initial accepted reference and maximum delta define the acceptance rule.','Reject a sudden measurement outside the configured delta from the last accepted sample.'],
 ['ONEQUANT','Nearest grid point','Numeric conversion','Stateless','signed/unsigned value + origin/step → snapped value','one_quant_i32, one_quant_u32','Numeric types and step domain are part of the API contract.','Quantize a control or measurement value to a fixed increment.'],
 ['ONERATE','Fractional event-rate generator','Rate generation','Stateful','numerator/denominator + phase → updated phase and emit flag','one_rate_step','Caller retains phase; each call advances one deterministic phase step.','Generate an event on three of every ten calls without a fractional timer.'],
 ['ONESCALE','Integer range conversion','Numeric conversion','Stateless','input range + output range + value → checked or clamped output','one_scale_u32 and signed/unsigned checked/clamp variants','Checked forms report out-of-range input; clamp variants map to an endpoint.','Convert a bounded ADC reading into a PWM range.'],
 ['ONESEQ','Cyclic sequence domain','Sequence arithmetic','Stateful configuration','bit width + sequence value → next/previous/distance/comparison','one_seq_init_bits, one_seq_next','Half-capacity distance is explicitly ambiguous; callers must check documented status.','Advance an 8-bit sequence from 255 back to 0 with explicit cyclic rules.'],
 ['ONESET','Packed membership set','Bounded container','Stateful descriptor','range + caller bytes; ID/key/index → add/remove/contains result','one_set_init_range, one_set_add_u32, one_set_contains_u32','Storage is caller allocated and sized through the required-byte API.','Track membership in a small fixed set without a general container.'],
 ['ONESLEW','Bounded step toward target','Control signal','Stateless with caller value','target + rise/fall limits + current value → bounded updated value','one_slew_i32, one_slew_u32','Zero limit is a hold; the operation does not overshoot the target.','Limit command movement per control-loop iteration.'],
 ['ONESTALE','Wrap-safe timestamp freshness','Freshness check','Stateless','now tick + updated tick + maximum age → fresh/stale result','one_stale_check','Maximum age must be below 0x80000000 to avoid half-range ambiguity.','Check freshness in a wrapping 32-bit tick counter.'],
 ['ONESTAT','Packed multi-field records','Bounded records','Stateful descriptor','record/field schema + caller bytes + operation → packed field result','one_stat_init_range, one_stat_get_u32, one_stat_add_u32','Field widths, required byte capacity and saturating arithmetic follow the schema contract.','Maintain compact bounded per-channel counters or small record sets.'],
 ['ONETRACE','Fixed-capacity ring trace','Diagnostics','Stateful descriptor','caller bytes + event → bounded ring; index → chronological entry','one_trace_init, one_trace_push, one_trace_get','Storage and record width are caller supplied; pushing when full overwrites the oldest entry.','Retain a compact recent event history for failure diagnosis.'],
 ['ONEVOTE','K-of-N sliding vote','Filtering / voting','Stateful','window size + threshold + boolean sample → rolling vote result','one_vote_init, one_vote_push','Window and threshold are configured and retained in caller-owned state.','Require three valid readings among the most recent five samples.'],
 ['ONEWINDOW','32-packet replay window','Protocol sequence filtering','Stateful','packet sequence + 32-bit window state → new/duplicate/old/ambiguous classification','one_window_reset, one_window_accept','Packets older than 31 positions and half-range ambiguous sequences are classified explicitly.','Reject duplicate or too-old sequence numbers in a bounded packet receive window.']
].map(([name,purpose,category,state,model,api,limits,typical])=>({name,purpose,category,state,model,api,limits,typical,id:name.toLowerCase()}));
const axiomCards=axiomModules.map(m=>`<article class="primitive-card"><span class="tag">${esc(m.category)}</span><h3>${esc(m.name)}</h3><p>${esc(m.purpose)}.</p><dl><dt>State</dt><dd>${esc(m.state)}</dd><dt>Model</dt><dd>${esc(m.model)}</dd></dl><a href="#${m.id}">Read ${esc(m.name)} details</a></article>`).join('');
const axiomDetails=axiomModules.map(m=>`<section class="primitive-detail" id="${m.id}"><h3>${esc(m.name)} — ${esc(m.purpose)}</h3><dl><dt>Category</dt><dd>${esc(m.category)}</dd><dt>State</dt><dd>${esc(m.state)}</dd><dt>Model</dt><dd>${esc(m.model)}</dd><dt>Public API</dt><dd><code>${esc(m.api)}</code></dd><dt>Typical use</dt><dd>${esc(m.typical)}</dd><dt>Limits</dt><dd>${esc(m.limits)}</dd></dl></section>`).join('');
const family=(name,list,file)=>`${head(`${name} — Vanderhell Development`,`${name} in the Vanderhell project portfolio.`,file)}<body>${nav('')}<main id="main"><header class="hero compact-hero"><div class="wrap"><div class="kicker">Project family</div><h1>${name}</h1></div></header><section class="section"><div class="wrap"><div class="portfolio-cards">${list.map(p=>card(p)).join('')}</div></div></section></main>${footer('')}</body></html>`;
const additionalLanding=`${head('Additional projects — Vanderhell Development','Independent systems, infrastructure and experimental research projects.','beyond-lox.html')}<body>${nav('')}<main id="main"><header class="hero compact-hero"><div class="wrap"><div class="kicker">Independent systems projects</div><h1>Additional projects</h1><p>Specialised infrastructure, deterministic research and embedded tools outside the LOX and Micro Toolkit families.</p></div></header><section class="section"><div class="wrap"><h2>Systems and infrastructure</h2><div class="portfolio-cards">${newProjects.filter(p=>p.slug==='basalt-net').map(p=>card(p)).join('')}</div><h2>Deterministic and research projects</h2><div class="portfolio-cards">${newProjects.filter(p=>p.slug!=='basalt-net').map(p=>card(p)).join('')}</div><h2>Other independent projects</h2><div class="portfolio-cards">${projects.filter(p=>p.group==='Beyond LOX').map(p=>card(p)).join('')}</div></div></section></main>${footer('')}</body></html>`;
const axiomFamily=`${head('Axiom One primitives — Vanderhell Development','Deterministic, allocation-free C primitives for bounded embedded problems.','axiom-one.html')}<body>${nav('')}<main id="main"><header class="hero compact-hero"><div class="wrap"><div class="kicker">Primitive family</div><h1>Axiom One primitives</h1><p>Three independent building blocks for bounded embedded work: a broad deterministic module library, table-free data placement, and heap-free traversal of implicit constrained spaces.</p></div></header><section class="section"><div class="wrap content-narrow"><h2>Small primitives, explicit boundaries</h2><p>This family is intentionally not a framework. Each component solves one narrow problem with deterministic behaviour, caller-owned state and no hidden allocation. They can stand alone in firmware where memory, timing and integration boundaries matter.</p><div class="portfolio-cards">${primitives.map(p=>card(p)).join('')}</div><h2>How the pieces differ</h2><div class="use-grid"><div class="panel"><strong>Axiom One</strong><br>22 general-purpose C99 primitives for scheduling, signal conditioning, protocol state and fixed-capacity containers.</div><div class="panel"><strong>GrayGyre</strong><br>A self-inverse Gray-code placement transform that spreads neighbouring indices across logical cells.</div><div class="panel"><strong>SkipSpace</strong><br>A sufficient-state traversal core that counts and skips subtrees without constructing the search tree.</div></div></div></section></main>${footer('')}</body></html>`;
const selected=['loxdb','basalt-net','nexum','loxc','axiom-one','umesh'].map(s=>s==='loxc'?unavailable:projects.find(p=>p.slug===s)||newProjects.find(p=>p.slug===s)||primitives.find(p=>p.slug===s));
const axiomCatalogPage=(url='axiom-one.html')=>`${head('Axiom One — deterministic C primitives','Axiom One is a portable C99 library of 22 independent deterministic primitives with caller-owned state and bounded interfaces.',url)}<body>${nav('')}<main id="main"><header class="hero compact-hero"><div class="wrap"><div class="kicker">Primitive library · portable C99</div><h1>Axiom One</h1><p>A dependency-free static library of 22 independent embedded-focused primitives. Each has a plain C API and a bounded problem scope; the umbrella header is convenient, while static linking includes only referenced module objects.</p><p>Modules retain state in caller-owned objects where state is required. Modules do not allocate heap memory, perform I/O or acquire hidden time/random inputs. They provide no timer or callback service; ONEINIT explicitly runs the ordered function list supplied by its caller. Stateless helpers remain stateless; inputs, outputs, state updates and error results are explicit in each API contract.</p><div class="badges"><span class="badge">22 modules</span><span class="badge">C99</span><span class="badge">MIT</span></div><div class="actions"><a class="button primary" href="https://github.com/Vanderhell/axiom-one">GitHub repository</a><a class="button secondary" href="#primitive-catalog">Browse primitives</a></div></div></header><section class="section"><div class="wrap"><h2>Axiom One as a library</h2><p class="lede">Composable, portable plain C building blocks for constrained systems. Caller-owned storage and state make ownership visible. Each operation accepts explicit inputs and returns explicit results; no hidden clock, random source or global mutable state is introduced by the modules.</p><p>Debug, Release, AddressSanitizer and MSVC warning-as-error test configurations are documented. A footprint report uses linker-map evidence for selected static library objects. These properties do not remove each module's documented domain, capacity or synchronization responsibilities.</p><h2 id="primitive-catalog">Axiom One primitives</h2><p>Each card links to the module's purpose, state model, API, typical use and limits below.</p><div class="primitive-grid">${axiomCards}</div><h2>Module details</h2>${axiomDetails}<p>Related independent projects: <a href="projects/graygyre.html">GrayGyre</a> and <a href="projects/skipspace.html">SkipSpace</a>. They remain separate repositories and portfolio projects.</p><p><a href="all-projects.html">All projects</a></p></div></section></main>${footer('')}</body></html>`;
const home=`${head('Vanderhell Development — systems and embedded software','Native systems and embedded software: storage, recovery, diagnostics and communication.','index.html')}<body>${nav('','home')}<main id="main"><header class="hero portfolio-hero"><div class="wrap"><div class="kicker">Independent systems software development</div><h1>Vanderhell Development</h1><p class="lede">Small native components and systems for constrained environments: storage, recovery, diagnostics, communication and deterministic control.</p><div class="actions"><a class="button primary" href="#selected">Selected projects</a><a class="button secondary" href="https://github.com/Vanderhell">GitHub</a></div></div></header><section class="section"><div class="wrap"><h2>What I build</h2><div class="areas"><article class="area"><h3>Persistent systems</h3><p>Databases, logs, configuration and power-loss recovery.</p></article><article class="area"><h3>Diagnostics & recovery</h3><p>Crash evidence, watchdogs, boot recovery and alarms.</p></article><article class="area"><h3>Communication</h3><p>LAN, mesh, queues and constrained protocols.</p></article><article class="area"><h3>Low-level building blocks</h3><p>Deterministic C components with explicit ownership and limits.</p></article></div></div></section><section class="section selected" id="selected"><div class="wrap"><h2>Selected projects</h2><div class="portfolio-cards">${selected.map(p=>card(p)).join('')}</div></div></section><section class="section family-section"><div class="wrap"><h2>Project families</h2><div class="families"><a href="lox-family.html"><h3>LOX Family</h3><p>Persistent state, recovery and diagnostics.</p></a><a href="micro-toolkit.html"><h3>Micro Toolkit</h3><p>Small independent components.</p></a><a href="axiom-one.html"><h3>Axiom One primitives</h3><p>Focused deterministic primitives for embedded constraints.</p></a><a href="beyond-lox.html"><h3>Beyond LOX</h3><p>Specialised systems work.</p></a></div><p><a href="all-projects.html">Find a project by engineering problem →</a></p></div></section></main>${footer('')}</body></html>`;
const all=[...projects,...newProjects,...primitives,toolkit,pro,unavailable];
const catalog=`${head('All Projects — Vanderhell Development','Complete project catalogue of '+all.length+' public projects.','all-projects.html')}<body>${nav('')}<main id="main"><header class="hero compact-hero"><div class="wrap"><h1>All projects</h1><p>${all.length} public repository projects across storage, infrastructure, deterministic research, diagnostics, communication and embedded software.</p></div></header><section class="section"><div class="wrap"><label class="search-label">Search projects <input id="project-search" type="search"></label><div class="portfolio-cards catalog-cards">${all.map(card).join('')}</div><p class="empty" hidden>No matching project.</p></div></section></main>${footer('')}</body></html>`;
const about=`${head('About Vanderhell Development','Independent systems and embedded software development.','about.html')}<body>${nav('','about')}<main id="main"><header class="hero compact-hero"><div class="wrap"><h1>Systems software, with boundaries made explicit.</h1><p>Independent developer focused on C/C++, embedded systems and relevant C#/.NET tooling.</p></div></header><section class="section"><div class="wrap content-narrow"><h2>Engineering focus</h2><p>Architecture, implementation, tests, documentation and release engineering for storage, persistence, diagnostics, communication, deterministic behaviour and constrained systems.</p><h2>Representative work</h2><div class="portfolio-cards">${selected.slice(0,4).map(card).join('')}</div></div></section></main>${footer('')}</body></html>`;
