const urls=['','lox-family.html','micro-toolkit.html','axiom-one.html','beyond-lox.html','all-projects.html','about.html',...all.map(p=>`projects/${p.slug}.html`)];write('sitemap.xml',`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${urls.map(u=>`<url><loc>https://vanderhell.github.io/${u}</loc></url>`).join('')}</urlset>`);write('robots.txt','User-agent: *\nAllow: /\nSitemap: https://vanderhell.github.io/sitemap.xml\n');
